oxy_webhelp_navlinks = {"archival_policy-d39536e6745":{"topics":[{"title":"Configuring an archival policy","shortdesc":"<p class=\"shortdesc\">When you create or edit a custom SLA Domain, configure the archival policy for the         SLA Domain to define which snapshots to archive, the archive schedule, and the archival         location.<\/p>","href":"saas\/configuring_archival_policy.html","attributes":{"data-id":"configuring_archival_policy"},"menu":{"hasChildren":false},"tocID":"configuring_archival_policy-d39536e6756","topics":[]},{"title":"Archival policy settings","shortdesc":"<p class=\"shortdesc\">Archival policies include settings for the archival location targets, tiering         policies, snapshot frequencies, archival threshold, and local retention.<\/p>","href":"cdm_old\/archival_policy_settings.html","attributes":{"data-id":"archival_policy_settings"},"menu":{"hasChildren":false},"tocID":"archival_policy_settings-d39536e6767","topics":[]},{"title":"Multiple archival policies","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> enables you to configure an SLA Domain with up to three archival         policies for data center workloads and up to two archival policies for cloud-native         workloads.<\/p>","href":"saas\/multiple_archival_policies.html","attributes":{"data-id":"multiple_archival_policies"},"menu":{"hasChildren":false},"tocID":"multiple_archival_policies-d39536e6778","topics":[]},{"title":"Cluster resource considerations for archival policies","shortdesc":"<p class=\"shortdesc\">An SLA Domain with more than two archival policies relies on a Rubrik cluster with         sufficient resources to upload snapshots to all configured archival         locations.<\/p>","href":"saas\/cluster_resources_archival_policies.html","attributes":{"data-id":"cluster_resources_archival_policies"},"menu":{"hasChildren":false},"tocID":"cluster_resources_archival_policies-d39536e6791","topics":[]},{"title":"Archive log snapshots with multiple archival policies","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> archives the log snapshots for database workloads to the location         with the higher archival frequency.<\/p>","href":"saas\/archive_log_snapshot_multiple_policies.html","attributes":{"data-id":"archive_log_snapshot_multiple_policies"},"menu":{"hasChildren":false},"tocID":"archive_log_snapshot_multiple_policies-d39536e6802","topics":[]},{"title":"Requirements and guidelines for archiving","shortdesc":"<p class=\"shortdesc\">An SLA Domain archival policy for data center workloads must meet specific         requirements.<\/p>","href":"saas\/requirements_guidelines_archiving.html","attributes":{"data-id":"requirements_guidelines_archiving"},"menu":{"hasChildren":false},"tocID":"requirements_guidelines_archiving-d39536e6815","topics":[]},{"title":"Archiving settings for specific workloads","shortdesc":"<p class=\"shortdesc\">Optional archiving settings for specific workloads when creating or editing an SLA         Domain.<\/p>","href":"saas\/archiving_settings_for_specific_workloads.html","attributes":{"data-id":"archiving_settings_for_specific_workloads"},"menu":{"hasChildren":false},"tocID":"archiving_settings_for_specific_workloads-d39536e6826","topics":[]}]}};